import type { AiFeature } from "../src/types";
import type { AgentRequest } from "./agentPrompts";

interface CaptureServerAiGenerationArgs {
  feature: AiFeature;
  provider: string;
  model: string;
  req: AgentRequest;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  spanName?: string;
  error?: unknown;
  evalSignals?: Record<string, unknown>;
}

const MAX_TEXT_CHARS = 6000;

function projectKey(): string | undefined {
  return process.env.POSTHOG_PROJECT_API_KEY ?? process.env.PUBLIC_POSTHOG_KEY;
}

function host(): string {
  return process.env.POSTHOG_HOST ?? "https://us.i.posthog.com";
}

function captureEnabled(): boolean {
  return process.env.POSTHOG_CAPTURE !== "false";
}

function clamp(text: string | undefined): string | undefined {
  if (!text) return text;
  if (text.length <= MAX_TEXT_CHARS) return text;
  return `${text.slice(0, MAX_TEXT_CHARS)}\n\n[truncated]`;
}

function id(prefix: string): string {
  return `${prefix}:${crypto.randomUUID()}`;
}

function errorValue(error: unknown): unknown {
  if (!error) return undefined;
  if (error instanceof Error) {
    return { message: error.message, name: error.name };
  }
  return String(error);
}

export async function captureServerAiGeneration({
  feature,
  provider,
  model,
  req,
  output,
  latencyMs,
  temperature,
  maxTokens,
  spanName,
  error,
  evalSignals,
}: CaptureServerAiGenerationArgs): Promise<void> {
  const apiKey = projectKey();
  if (!apiKey || !captureEnabled()) return;

  try {
    await fetch(`${host().replace(/\/$/, "")}/i/v0/e/`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        api_key: apiKey,
        event: "$ai_generation",
        properties: {
          distinct_id: "convex-server",
          $ai_trace_id: id(feature),
          $ai_span_id: id(`${feature}:server-generation`),
          $ai_span_name: spanName ?? feature,
          $ai_model: model,
          $ai_provider: provider,
          $ai_input: [
            {
              role: "user",
              content: clamp(
                JSON.stringify({
                  persona: req.persona.id,
                  instruction: req.instruction ?? "feedback",
                  hasBrief: !!req.brief,
                  draftText: req.draftText,
                  anchor: req.anchor,
                  userMessage: req.userMessage,
                }),
              ),
            },
          ],
          $ai_output_choices: output
            ? [{ role: "assistant", content: clamp(output) }]
            : [],
          $ai_latency: latencyMs / 1000,
          $ai_temperature: temperature,
          $ai_max_tokens: maxTokens,
          $ai_is_error: !!error,
          $ai_error: errorValue(error),
          twyne_feature: feature,
          twyne_persona_id: req.persona.id,
          twyne_instruction: req.instruction ?? "feedback",
          twyne_server_runtime: "convex",
          ...evalSignals,
        },
      }),
    });
  } catch (err) {
    console.warn("[twyne:posthog] failed to capture AI generation:", err);
  }
}

"use node";

/**
 * Arize / Phoenix OpenInference tracer for Convex "use node" actions.
 *
 * Mirrors the dormant-when-unconfigured style of `convex/posthog.ts`: if the
 * Arize credentials are not in the deployment env we skip registering a
 * provider and turn `flushArize()` into a no-op. Convex actions are
 * serverless / short-lived, so we use `OpenInferenceSimpleSpanProcessor`
 * (synchronous export per span) rather than `BatchSpanProcessor`, which can
 * drop spans when the runtime freezes mid-batch. Each action must call
 * `await flushArize()` right before it returns so the in-flight spans
 * finish posting.
 */
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
import {
  isOpenInferenceSpan,
  OpenInferenceSimpleSpanProcessor,
} from "@arizeai/openinference-vercel";

const ARIZE_API_KEY = process.env.ARIZE_API_KEY;
const ARIZE_SPACE_ID = process.env.ARIZE_SPACE_ID;
const ARIZE_PROJECT_NAME =
  process.env.ARIZE_PROJECT_NAME ?? "twyne";
// Arize is region-sharded. The OTLP host is region-specific
// (otlp.<region>.arize.com); the US default would silently 401 a CA space.
// Override the full endpoint, or just the region, via env.
const ARIZE_REGION = process.env.ARIZE_REGION ?? "ca-central-1a";
const ARIZE_OTLP_ENDPOINT =
  process.env.ARIZE_OTLP_ENDPOINT ??
  `https://otlp.${ARIZE_REGION}.arize.com/v1/traces`;

export const tracingEnabled = Boolean(
  ARIZE_API_KEY && ARIZE_SPACE_ID,
);

let provider: NodeTracerProvider | null = null;

if (tracingEnabled) {
  provider = new NodeTracerProvider({
    resource: resourceFromAttributes({
      model_id: ARIZE_PROJECT_NAME,
      model_version: "1.0.0",
    }),
    spanProcessors: [
      new OpenInferenceSimpleSpanProcessor({
        exporter: new OTLPTraceExporter({
          url: ARIZE_OTLP_ENDPOINT,
          headers: {
            "arize-space-id": ARIZE_SPACE_ID as string,
            "arize-api-key": ARIZE_API_KEY as string,
          },
        }),
        spanFilter: isOpenInferenceSpan,
        reparentOrphanedSpans: true,
      }),
    ],
  });
  provider.register();
}

export async function flushArize(): Promise<void> {
  if (!provider) return;
  try {
    await provider.forceFlush();
  } catch (err) {
    console.warn("[twyne:arize] failed to flush spans:", err);
  }
}

import { capturePostHogEvent } from "./posthog-context";
import { getRuntimeFeatures } from "./feature-flags";

interface AiEvalCapture {
  feature: string;
  provider: string;
  model: string;
  system?: string;
  prompt: string;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  traceId?: string;
  spanName?: string;
  error?: unknown;
  evalSignals?: Record<string, unknown>;
}

const MAX_TEXT_CHARS = 6000;

function clampText(text: string | undefined): string | undefined {
  if (!text) return text;
  if (text.length <= MAX_TEXT_CHARS) return text;
  return `${text.slice(0, MAX_TEXT_CHARS)}\n\n[truncated]`;
}

function traceId(feature: string): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return `${feature}:${crypto.randomUUID()}`;
  }
  return `${feature}:${Date.now()}:${Math.random().toString(36).slice(2)}`;
}

function countWords(text: string | undefined): number {
  return text?.trim().split(/\s+/).filter(Boolean).length ?? 0;
}

export async function captureAiGeneration({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  spanName,
  error,
  evalSignals,
}: AiEvalCapture): Promise<void> {
  await capturePostHogEvent(
    "$ai_generation",
    buildAiGenerationProperties({
      feature,
      provider,
      model,
      system,
      prompt,
      output,
      latencyMs,
      temperature,
      maxTokens,
      traceId: explicitTraceId,
      spanName,
      error,
      evalSignals,
    }),
  );
}

export function buildAiGenerationProperties({
  feature,
  provider,
  model,
  system,
  prompt,
  output,
  latencyMs,
  temperature,
  maxTokens,
  traceId: explicitTraceId,
  spanName,
  error,
  evalSignals,
}: AiEvalCapture): Record<string, unknown> {
  const features = getRuntimeFeatures();
  return {
    $ai_trace_id: explicitTraceId ?? traceId(feature),
    $ai_span_id: traceId(`${feature}:generation`),
    $ai_span_name: spanName ?? feature,
    $ai_model: model,
    $ai_provider: provider,
    $ai_input: [
      ...(system ? [{ role: "system", content: clampText(system) }] : []),
      { role: "user", content: clampText(prompt) },
    ],
    $ai_output_choices: output
      ? [{ role: "assistant", content: clampText(output) }]
      : [],
    $ai_latency: latencyMs / 1000,
    $ai_temperature: temperature,
    $ai_max_tokens: maxTokens,
    $ai_is_error: !!error,
    $ai_error:
      error instanceof Error
        ? { message: error.message, name: error.name }
        : error
          ? String(error)
          : undefined,
    twyne_feature: feature,
    twyne_runtime_pricing_flag: features.pricing,
    twyne_runtime_local_ai_flag: features.localAi,
    twyne_output_words: countWords(output),
    twyne_prompt_words: countWords(prompt) + countWords(system),
    ...evalSignals,
  };
}

import {
  component$,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  type Signal,
} from "@builder.io/qwik";
import type posthog from "posthog-js";
import { useAuth } from "./auth-context";
import {
  FALLBACK_FEATURES,
  POSTHOG_FEATURE_FLAG_KEYS,
  setRuntimeFeatures,
  type FeatureFlags,
} from "./feature-flags";
import { buildPostHogInitOptions } from "./posthog-config";

interface FeatureFlagState {
  flags: FeatureFlags;
  loaded: boolean;
  configured: boolean;
  error?: string;
}

type PostHogClient = typeof posthog;

export const FeatureFlagContext = createContextId<Signal<FeatureFlagState>>(
  "twyne.feature-flags",
);

let clientPromise: Promise<PostHogClient | null> | null = null;
let initialized = false;

function posthogConfig(): {
  key: string;
  host: string;
  capture: boolean;
} | null {
  const key = import.meta.env.PUBLIC_POSTHOG_KEY as string | undefined;
  if (!key) return null;
  return {
    key,
    host:
      (import.meta.env.PUBLIC_POSTHOG_HOST as string | undefined) ??
      "https://us.i.posthog.com",
    capture: import.meta.env.PUBLIC_POSTHOG_CAPTURE !== "false",
  };
}

async function getPostHogClient(): Promise<PostHogClient | null> {
  if (typeof window === "undefined") return null;
  const config = posthogConfig();
  if (!config) return null;

  clientPromise ??= import("posthog-js").then((mod) => {
    const client = mod.default;
    if (!initialized) {
      client.init(
        config.key,
        buildPostHogInitOptions({
          host: config.host,
          capture: config.capture,
          flagKeys: Object.values(POSTHOG_FEATURE_FLAG_KEYS),
        }),
      );
      initialized = true;
    }
    return client;
  });

  return clientPromise;
}

export async function capturePostHogEvent(
  event: string,
  properties: Record<string, unknown>,
): Promise<void> {
  const client = await getPostHogClient();
  if (!client) return;
  client.capture(event, properties);
}

function readFlags(client: PostHogClient): FeatureFlags {
  return {
    pricing:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.pricing) ??
      FALLBACK_FEATURES.pricing,
    localAi:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.localAi) ??
      FALLBACK_FEATURES.localAi,
  };
}

export function useFeatureFlags(): Signal<FeatureFlagState> {
  return useContext(FeatureFlagContext);
}

export const PostHogProvider = component$(() => {
  const flags = useSignal<FeatureFlagState>({
    flags: FALLBACK_FEATURES,
    loaded: !posthogConfig(),
    configured: !!posthogConfig(),
  });
  const auth = useAuth();

  useContextProvider(FeatureFlagContext, flags);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const client = await getPostHogClient();
    if (!client) {
      setRuntimeFeatures(FALLBACK_FEATURES);
      flags.value = {
        flags: FALLBACK_FEATURES,
        loaded: true,
        configured: false,
      };
      return;
    }

    const apply = (next: FeatureFlags, error?: string) => {
      setRuntimeFeatures(next);
      flags.value = {
        flags: next,
        loaded: true,
        configured: true,
        error,
      };
    };

    const unsubscribe = client.onFeatureFlags((_keys, _variants, meta) => {
      const next = meta?.errorsLoading ? FALLBACK_FEATURES : readFlags(client);
      apply(
        next,
        meta?.errorsLoading
          ? "PostHog feature flags failed to load"
          : undefined,
      );
    });

    const cached = readFlags(client);
    apply(cached);

    if (typeof unsubscribe === "function") {
      cleanup(unsubscribe);
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    track(() => auth.value.user?.id);
    track(() => auth.value.user?.email);
    track(() => auth.value.user?.name);
    track(() => auth.value.loading);
    track(() => auth.value.provider);

    const client = await getPostHogClient();
    if (!client || auth.value.loading) return;

    if (auth.value.user) {
      const previousUserId = client.get_property("$user_id");
      if (previousUserId && previousUserId !== auth.value.user.id) {
        client.reset();
      }
      client.identify(auth.value.user.id, {
        email: auth.value.user.email,
        name: auth.value.user.name,
        auth_provider: auth.value.provider,
      });

      if (previousUserId !== auth.value.user.id) {
        client.capture("sign_in_completed", {
          analytics_version: 1,
          provider: auth.value.provider ?? "convex",
        });
      }
    } else if (client.get_property("$user_id")) {
      // `reset()` creates a fresh anonymous id. Only do that when an
      // identified session actually ended; resetting every anonymous page
      // load made the same returning writer look like a brand-new person.
      client.reset();
    }
  });

  return <Slot />;
});
import type { PostHogConfig } from "posthog-js";

/**
 * Keep this aligned with the current PostHog recommended defaults. The
 * explicit history setting below is intentional: a future defaults change
 * must never silently turn Qwik City navigation back into load-only tracking.
 */
export const POSTHOG_DEFAULTS_VERSION = "2026-05-30";

interface PostHogInitOptions {
  host: string;
  capture: boolean;
  flagKeys: string[];
}

export function buildPostHogInitOptions({
  host,
  capture,
  flagKeys,
}: PostHogInitOptions): Partial<PostHogConfig> {
  return {
    api_host: host,
    defaults: POSTHOG_DEFAULTS_VERSION,
    autocapture: capture,
    capture_pageview: capture ? "history_change" : false,
    capture_pageleave: capture,
    disable_session_recording: !capture,
    opt_out_capturing_by_default: !capture,
    flag_keys: flagKeys,
  };
}
