 19	import { buildPostHogInitOptions } from "./posthog-config";
 20	
 21	interface FeatureFlagState {
 22	  flags: FeatureFlags;
 23	  loaded: boolean;
 24	  configured: boolean;
 25	  error?: string;
 26	}
 27	
 28	type PostHogClient = typeof posthog;
 29	
 30	export const FeatureFlagContext = createContextId<Signal<FeatureFlagState>>(
 31	  "twyne.feature-flags",
 32	);
 33	
 34	let clientPromise: Promise<PostHogClient | null> | null = null;
 35	let initialized = false;
 36	
 37	function posthogConfig(): {
 38	  key: string;
 39	  host: string;
 40	  capture: boolean;
 41	} | null {
 42	  const key = import.meta.env.PUBLIC_POSTHOG_KEY as string | undefined;
 43	  if (!key) return null;
 44	  return {
 45	    key,
 46	    host:
 47	      (import.meta.env.PUBLIC_POSTHOG_HOST as string | undefined) ??
 48	      "https://us.i.posthog.com",
 49	    capture: import.meta.env.PUBLIC_POSTHOG_CAPTURE !== "false",
 50	  };
 51	}
 52	
 53	async function getPostHogClient(): Promise<PostHogClient | null> {
 54	  if (typeof window === "undefined") return null;
 55	  const config = posthogConfig();
 56	  if (!config) return null;
 57	
 58	  clientPromise ??= import("posthog-js").then((mod) => {
 59	    const client = mod.default;
 60	    if (!initialized) {
 61	      client.init(
 62	        config.key,
 63	        buildPostHogInitOptions({
 64	          host: config.host,
 65	          capture: config.capture,
 66	          flagKeys: Object.values(POSTHOG_FEATURE_FLAG_KEYS),
 67	        }),
 68	      );
 69	      initialized = true;
 70	    }
 71	    return client;
 72	  });
 73	
 74	  return clientPromise;
 75	}
 76	
 77	export async function capturePostHogEvent(
 78	  event: string,
 79	  properties: Record<string, unknown>,
 80	): Promise<void> {
 81	  const client = await getPostHogClient();
 82	  if (!client) return;
 83	  client.capture(event, properties);
 84	}
 85	
 86	function readFlags(client: PostHogClient): FeatureFlags {
 87	  return {
 88	    pricing:
 89	      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.pricing) ??
 90	      FALLBACK_FEATURES.pricing,
 91	    localAi:
 92	      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.localAi) ??
 93	      FALLBACK_FEATURES.localAi,
 94	  };
 95	}
 96	
 97	export function useFeatureFlags(): Signal<FeatureFlagState> {
 98	  return useContext(FeatureFlagContext);
 99	}
100	
101	export const PostHogProvider = component$(() => {
102	  const flags = useSignal<FeatureFlagState>({
103	    flags: FALLBACK_FEATURES,
104	    loaded: !posthogConfig(),
105	    configured: !!posthogConfig(),
106	  });
107	  const auth = useAuth();
108	
109	  useContextProvider(FeatureFlagContext, flags);
110	
111	  // eslint-disable-next-line qwik/no-use-visible-task
112	  useVisibleTask$(async ({ cleanup }) => {
113	    const client = await getPostHogClient();
114	    if (!client) {
115	      setRuntimeFeatures(FALLBACK_FEATURES);
116	      flags.value = {
117	        flags: FALLBACK_FEATURES,
118	        loaded: true,
119	        configured: false,
120	      };
121	      return;
122	    }
123	
124	    const apply = (next: FeatureFlags, error?: string) => {
125	      setRuntimeFeatures(next);
126	      flags.value = {
127	        flags: next,
128	        loaded: true,
129	        configured: true,
130	        error,
131	      };
132	    };
133	
134	    const unsubscribe = client.onFeatureFlags((_keys, _variants, meta) => {
135	      const next = meta?.errorsLoading ? FALLBACK_FEATURES : readFlags(client);
136	      apply(
137	        next,
138	        meta?.errorsLoading
139	          ? "PostHog feature flags failed to load"
140	          : undefined,
141	      );
142	    });
143	
144	    const cached = readFlags(client);
145	    apply(cached);
146	
147	    if (typeof unsubscribe === "function") {
148	      cleanup(unsubscribe);
149	    }
150	  });
151	
152	  // eslint-disable-next-line qwik/no-use-visible-task
153	  useVisibleTask$(async ({ track }) => {
154	    track(() => auth.value.user?.id);
155	    track(() => auth.value.user?.email);
156	    track(() => auth.value.user?.name);
157	    track(() => auth.value.loading);
158	    track(() => auth.value.provider);
159	
160	    const client = await getPostHogClient();
161	    if (!client || auth.value.loading) return;
162	
163	    if (auth.value.user) {
164	      const previousUserId = client.get_property("$user_id");
165	      if (previousUserId && previousUserId !== auth.value.user.id) {
166	        client.reset();
167	      }
168	      client.identify(auth.value.user.id, {
169	        email: auth.value.user.email,
170	        name: auth.value.user.name,
171	        auth_provider: auth.value.provider,
172	      });
173	
174	      if (previousUserId !== auth.value.user.id) {
175	        client.capture("sign_in_completed", {
176	          analytics_version: 1,
177	          provider: auth.value.provider ?? "convex",
178	        });
179	      }
180	    } else if (client.get_property("$user_id")) {
181	      // `reset()` creates a fresh anonymous id. Only do that when an
182	      // identified session actually ended; resetting every anonymous page
183	      // load made the same returning writer look like a brand-new person.
184	      client.reset();
185	    }
