  provider: string;
  model: string;
  system?: string;
  prompt: string;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  traceId?: string;
  spanName?: string;
  error?: unknown;
  evalSignals?: Record<string, unknown>;
