const typeOrder: FeedbackType[] = [
  "critique",
  "suggestion",
  "encouragement",
  "perspective",
];

function classifyType(text: string, fallback: FeedbackType): FeedbackType {
  const scores = typeOrder.map((t) => ({
    t,
    score: (text.match(typeKeywords[t]) ?? []).length,
  }));
  scores.sort((a, b) => b.score - a.score);
  if (scores[0]?.score > 0) return scores[0].t;
  return fallback;
}

/* ── LLM call wrapper ───────────────────────────────────────────── */

async function runLlm(
  provider: ProviderConfig,
  req: AgentRequest,
  feature:
    | "persona-feedback"
    | "persona-reply"
    | "persona-analysis" = "persona-feedback",
  maxTokens = 380,
): Promise<AgentResponse> {
  const system = buildSystemPrompt(req.persona);
  const user = buildUserPrompt(req);
  const fallbackType: FeedbackType = defaultTypeForPersona(req.persona);
  const temperature =
    req.persona.temperature ??
    (provider.label === "openai" ? 0.6 : 0.4);
  const start = Date.now();
  const { tools, getAnchor } = buildQuoteTools(req.draftText);

  try {
    const { text } = await generateText({
      model: provider.model,
      system,
      prompt: user,
      temperature,
      maxOutputTokens: maxTokens,
      tools,
      stopWhen: stepCountIs(3),
      experimental_telemetry: {
        isEnabled: tracingEnabled,
        functionId: feature,
        metadata: {
          feature,
          persona: req.persona.id,
          provider: provider.label,
          model: provider.modelId,
        },
      },
    });
    let visibleText = stripReasoningTags(text);
    // Any reply that reached for the reasoning channel is discarded and asked
    // again, not merely stripped: a note with the model's thinking bleeding
    // through it reads worse than one that cost a second call.
    if (!visibleText || hasReasoningTags(text)) {
      const retry = await generateText({
        model: provider.model,
        system,
        prompt: `${user}\n\nRespond with your note as plain visible text. Do not place your whole answer inside <think> tags.`,
        temperature,
        maxOutputTokens: maxTokens,
        tools,
        stopWhen: stepCountIs(3),
        experimental_telemetry: {
          isEnabled: tracingEnabled,
          functionId: `${feature}:retry`,
          metadata: {
            feature,
            persona: req.persona.id,
            provider: provider.label,
            model: provider.modelId,
          },
        },
      });
      const retryVisible = stripReasoningTags(retry.text);
      visibleText =
        (!hasReasoningTags(retry.text) && retryVisible) ||
        visibleText ||
        retryVisible ||
        removeReasoningTagMarkers(retry.text);
    }
    await captureServerAiGeneration({
      feature,
      provider: provider.label,
      model: provider.modelId,
      req,
      output: visibleText,
      latencyMs: Date.now() - start,
      temperature,
      maxTokens,
      spanName: feature,
    });

    const cleaned = visibleText.trim();
    await flushArize();
    return {
      text: cleaned || "(no response)",
      type: classifyType(cleaned, fallbackType),
      provider: provider.label,
      anchor: getAnchor() ?? req.anchor,
    };
  } catch (err) {
    await captureServerAiGeneration({
      feature,
      provider: provider.label,
      model: provider.modelId,
      req,
      latencyMs: Date.now() - start,
      temperature,
      maxTokens,
      spanName: feature,
      error: err,
    });
    await flushArize();
    throw err;
  }
}

